<script setup lang="ts">
import WorkbenchNavIcon from './WorkbenchNavIcon.vue';
import {reactive,ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import type {Template,Platform} from '@/domain/types';
import {assetUrl} from '@/services/api';
import {pageNames} from '@/domain/presentation';
import AppExperience from '@/components/AppExperience.vue';
import PufferMark from '@/components/PufferMark.vue';
import ThemeStudioMark from './ThemeStudioMark.vue';
import AppearanceToggle from './AppearanceToggle.vue';
import Inspector from './ThemeInspector.vue';
import {useWorkbench,devices} from './useWorkbench';
import './workbench.css';
import OfflineSettings from './OfflineSettings.vue';
import ClientIntegration from './ClientIntegration.vue';
const productPage=ref('');
const w=reactive(useWorkbench());
const canvas=ref<any>(null),canvasWidth=ref(900),canvasHeight=ref(850),zoom=ref('fit');
let observer:ResizeObserver|undefined;
let canvasElement:HTMLElement|undefined;
const zoomPresets=[.25,.5,.75,1,1.25,1.5,2];
const customZoom=computed(()=>zoom.value!=='fit'&&!zoomPresets.includes(Number(zoom.value)));
function zoomCanvas(event:WheelEvent){
 if(!event.ctrlKey)return;
 event.preventDefault();event.stopPropagation();
 if(!event.deltaY)return;
 const delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?canvasHeight.value:1);
 zoom.value=String(Math.round(Math.max(.15,Math.min(2,scale.value*Math.exp(-Math.max(-120,Math.min(120,delta))*.002)))*1000)/1000);
}
function releaseCanvas(){observer?.disconnect();canvasElement?.removeEventListener('wheel',zoomCanvas,true);canvasElement=undefined;}
const tools=[{id:'brand',name:'品牌界面',icon:'◈'},{id:'colors',name:'主题配色',icon:'◐'},{id:'carousel',name:'轮播设计',icon:'▣'},{id:'navigation',name:'导航样式',icon:'☷'},{id:'festival',name:'节日装饰',icon:'✧'},{id:'startup',name:'开机页面',icon:'◷'}];
const scale=computed(()=>{if(zoom.value!=='fit')return Number(zoom.value);const width=(canvasWidth.value-56)/w.activeDevice.width;const height=(canvasHeight.value-48)/w.activeDevice.height;return Math.max(.15,Math.min(1.1,w.device==='mobile'&&!w.fullPreview?width:Math.min(width,height)));});
const canvasStyle=computed(()=>({width:w.activeDevice.width+'px',height:w.activeDevice.height+'px',transform:'scale('+scale.value+')'}));
const holderStyle=computed(()=>({width:w.activeDevice.width*scale.value+'px',height:w.activeDevice.height*scale.value+'px'}));
const dialogTitles:Record<string,string>={import:'安装主题骨架',rename:'修改主题名称',duplicate:'复制为新主题',remove:'删除主题',guide:'制作与交付流程'};
function inspect(id:string){w.tool=id;w.selected=id==='carousel'?'hero':id;}
function thumbnail(t:Template){return t.draft.carousel.slides.find(s=>s.image)?.image||'';}
function sizeCanvas(){releaseCanvas();const el=canvas.value?.$el||canvas.value;if(!el)return;canvasElement=el;el.addEventListener('wheel',zoomCanvas,{passive:false,capture:true});observer=new ResizeObserver(entries=>{const r=entries[0].contentRect;canvasWidth.value=r.width;canvasHeight.value=r.height;});observer.observe(el);}
watch(()=>[w.view,w.fullPreview,productPage.value],async()=>{await nextTick();sizeCanvas();});
onMounted(()=>nextTick(sizeCanvas));onUnmounted(releaseCanvas);
</script>
<template>
<view class="workbench" :class="[w.mode,{fullscreen:w.fullPreview}]">
<view class="app-rail"><view class="rail-brand"><ThemeStudioMark :size="38"/></view><button class="rail-button" :class="{active:!productPage&&w.view==='library'}" title="主题库" aria-label="主题库" @click="productPage='';w.library()"><WorkbenchNavIcon name="library"/><span class="rail-label">主题库</span></button><button class="rail-button" :disabled="!w.current||!w.serviceReady" :class="{active:!productPage&&w.view==='editor'}" title="主题编辑" aria-label="主题编辑" @click="productPage='';w.current&&w.openTemplate(w.current)"><WorkbenchNavIcon name="editor"/><span class="rail-label">主题编辑</span></button><view class="rail-spacer"/><button class="rail-button" :class="{active:productPage==='settings'}" title="设置" aria-label="设置" @click="productPage='settings'"><WorkbenchNavIcon name="settings"/><span class="rail-label">设置</span></button></view>
<view class="workbench-main"><view class="local-packer-status" role="status"><text class="status-dot" :class="{online:w.packerConnected}"/><text>{{w.packerConnected?'已连接本机打包器 · 本地自动同步':'等待本机打包器启动 · 启动后自动连接'}}</text></view>
<view class="product-host" :class="{'settings-layout':productPage==='settings'}">
<aside v-if="productPage==='settings'" class="settings-navigation" aria-label="设置导航">
<div class="settings-heading"><div><span class="eyebrow">PREFERENCES</span><h1>设置</h1></div><AppearanceToggle :mode="w.mode" @toggle="w.toggleMode()"/></div>
<p class="settings-intro">管理你的主题中心</p>
<nav class="settings-links"><button class="selected" aria-current="page"><WorkbenchNavIcon name="settings"/><span><strong>本机与离线</strong><small>本地保存、素材与导出</small></span></button><button @click="w.dialog='guide'"><WorkbenchNavIcon name="help"/><span><strong>使用指南</strong><small>从安装主题到导出使用</small></span><b aria-hidden="true">↗</b></button></nav>
<div class="settings-footer"><ThemeStudioMark/><span>河豚主题中心<small>让每一份创作，都有自己的风格。</small></span></div>
</aside>
<OfflineSettings v-if="productPage==='settings'"/>
</view>
<view v-if="!productPage&&w.view==='library'" class="library-page">
<view class="library-header"><view><text class="eyebrow">HETUN THEME STUDIO</text><text class="library-title">河豚主题中心<text class="version-tag">0.2.11</text></text><text class="library-subtitle">把你的品牌，做成一套完整的影视体验。</text></view><view class="header-actions"><AppearanceToggle :mode="w.mode" @toggle="w.toggleMode()"/><button class="primary" @click="w.importDialog()" :disabled="!w.serviceReady||w.busy">＋ 安装主题包</button></view></view>
<view class="library-controls"><view class="platform-tabs"><button v-for="d in devices" :key="d.id" :class="{active:w.device===d.id}" @click="w.chooseDevice(d.id)"><text>{{d.name}}</text><text class="tab-count">{{w.templates.filter(t=>t.platform===d.id).length}}</text></button></view><view class="library-search"><text>⌕</text><input v-model="w.search" placeholder="搜索主题名称" maxlength="60"/><button v-if="w.search" aria-label="清除搜索" @click="w.search=''">×</button></view></view>
<view class="library-summary"><text>{{w.activeDevice.name}}主题<text class="summary-count">{{w.filtered.length}} 套</text></text><text>每套骨架拥有自己的页面结构与设计草稿</text></view>
<view v-if="w.loading" class="library-empty"><view class="empty-symbol">◌</view><text>正在读取主题库…</text></view>
<view v-else-if="!w.serviceReady" class="library-empty"><view class="empty-symbol">↻</view><text class="empty-title">主题库暂时无法读取</text><text>请重试读取，或重新启动主题中心。</text><button class="primary" @click="w.loadWorkspace()">重新读取</button></view>
<view v-else-if="!w.filtered.length" class="library-empty"><view class="empty-symbol">▦</view><text class="empty-title">{{w.search?'没有匹配的主题':'还没有安装'+w.activeDevice.name+'骨架'}}</text><text>{{w.search?'换一个名称搜索，或清除搜索条件。':'上传该端的主题包，识别安装后即可编辑。'}}</text><button v-if="!w.search" class="primary" @click="w.importDialog()">安装{{w.activeDevice.name}}主题包</button></view>
<view v-else class="theme-grid"><view v-for="t in w.filtered" :key="t.id" class="theme-card"><button class="theme-cover" :style="{'--cover-bg':t.draft.colors.background,'--cover-accent':t.draft.colors.accent}" :disabled="w.busy" @click="w.openTemplate(t)"><view class="cover-top"><text class="cover-dot"/><text>{{t.draft.brand.name}}</text><text class="cover-label">{{w.activeDevice.short}}</text></view><view class="cover-art"><image v-if="thumbnail(t)" :src="assetUrl(thumbnail(t))" mode="aspectFill"/><view v-else class="cover-original"><PufferMark :size="58"/><text>{{t.draft.brand.name}}</text><text class="cover-original-sub">{{t.draft.brand.tagline||'YOUR CINEMA. YOUR STYLE.'}}</text></view></view><view class="cover-lines"><view v-for="n in 3" :key="n"><view/><view/></view></view><view class="cover-open">打开编辑器 ↗</view></button><view class="theme-info"><view><text class="theme-name">{{t.name}}</text><text class="theme-meta">{{w.activeDevice.name}}骨架 · {{t.draft.sections.length}} 个内容模块</text></view><text class="draft-badge">{{t.published?'已发布':'草稿'}}</text></view><view class="theme-actions"><button class="open-editor" :disabled="w.busy" @click="w.openTemplate(t)">编辑主题 →</button><button :disabled="w.busy" @click="w.manage(t,'rename')">改名</button><button :disabled="w.busy" @click="w.manage(t,'duplicate')">复制</button><button class="danger subtle" :disabled="w.busy" @click="w.manage(t,'remove')">删除</button></view></view><button class="theme-add" @click="w.importDialog()"><text class="add-symbol">＋</text><text>安装新骨架</text><text class="theme-meta">ZIP / JSON 主题包</text></button></view>
<view class="library-footer"><view><text class="status-dot" :class="{online:w.serviceReady}"/>{{w.serviceReady?'本机主题库已就绪':'正在连接本机服务'}}</view><text>主题制作 → 配置多端接入 → 导出给打包器 / 运营中心</text><button class="subtle" @click="w.dialog='guide'">了解交付流程 ↗</button></view>
</view>
<template v-else-if="!productPage">
<view class="editor-command"><view class="editor-identity"><button class="back-button" @click="w.library()">← 主题库</button><view class="command-divider"/><view><text class="editor-name">{{w.current?.name}}</text><text class="editor-sub">{{w.activeDevice.name}}骨架 <text class="unsaved" v-if="w.dirty">· 未保存</text><text v-else>· 已保存</text></text></view></view><view class="editor-actions"><AppearanceToggle :mode="w.mode" @toggle="w.toggleMode()"/><button class="icon-button" :disabled="!w.canUndo||w.locked||w.busy" title="撤销 Ctrl+Z" aria-label="撤销" @click="w.undo()">↶</button><button class="icon-button" :disabled="!w.canRedo||w.locked||w.busy" title="重做 Ctrl+Shift+Z" aria-label="重做" @click="w.redo()">↷</button><view class="command-divider"/><button :disabled="w.locked||w.busy" @click="w.dialog='integration'">多端接入</button><button :disabled="w.locked||w.busy" @click="w.save()">保存草稿</button><button :disabled="w.locked||w.busy" @click="w.publishPreview()">本机发布</button><button :disabled="w.locked||w.busy" @click="w.sendToPacker()">发送到本机打包器</button><button class="primary" :disabled="w.locked||w.busy" @click="w.exportPackage()">导出主题包 ↗</button></view></view>
<view class="editor-workspace">
<view class="structure-panel"><view class="structure-tabs"><text>页面与设计</text><text class="small-badge">{{w.activeDevice.short}}</text></view><view class="structure-scroll"><view class="tree-heading">设计工具</view><view class="design-tools"><button v-for="t in tools" :key="t.id" :class="{active:w.tool===t.id}" @click="inspect(t.id)"><text>{{t.icon}}</text><text>{{t.name}}</text></button></view><view class="tree-heading">页面 <text>{{w.pageList.length}}</text></view><button v-for="p in w.pageList" :key="p.id" class="page-node" :class="{active:w.page===p.id}" @click="w.selectPage(p.id)"><text class="page-icon">▤</text><text>{{p.name}}</text><text class="node-muted">{{p.enabled?'':'未启用'}}</text></button><view class="tree-heading">当前页面模块 <button title="添加模块" aria-label="添加模块" :disabled="w.locked||w.theme.sections.length>=40" @click="w.addModule()">＋</button></view><button v-if="w.page==='home'" class="module-node" :class="{active:w.selected==='hero'}" @click="w.selectElement('hero')"><text>▣</text><text>首页轮播</text></button><view v-for="(s,i) in w.pageSections" :key="s.id" class="module-row" :class="{active:w.selected===s.id}"><button class="module-node" @click="w.selectElement(s.id)"><text>▦</text><text>{{s.title||'未命名模块'}}</text><text class="node-muted">{{s.enabled?'':'隐藏'}}</text></button><view class="module-sort"><button :disabled="i===0||w.locked" title="模块上移" aria-label="模块上移" @click="w.moveModule(s,-1)">↑</button><button :disabled="i===w.pageSections.length-1||w.locked" title="模块下移" aria-label="模块下移" @click="w.moveModule(s,1)">↓</button></view></view><view v-if="!w.pageSections.length" class="tree-empty">此页没有自定义内容模块</view></view><view class="structure-foot"><text class="status-dot"/><text>离线预览 · 本机素材</text></view></view>
<view class="canvas-panel"><view class="canvas-toolbar"><view class="canvas-location"><text>{{pageNames[w.page]}}</text><text class="canvas-size">{{w.activeDevice.width}} × {{w.activeDevice.height}}</text></view><view class="canvas-tools"><view class="mode-segment"><button :class="{active:w.interactive}" @click="w.interactive=true">交互预览</button><button :class="{active:!w.interactive}" @click="w.interactive=false">选取编辑</button></view><select v-model="zoom" aria-label="画布缩放" title="按住 Ctrl 并滚动鼠标滚轮缩放画布"><option value="fit">适应画布</option><option v-if="customZoom" :value="zoom">{{Math.round(scale*100)}}%</option><option v-for="preset in zoomPresets" :key="preset" :value="String(preset)">{{Math.round(preset*100)}}%</option></select><button class="icon-button" :title="w.fullPreview?'退出大画布':'放大画布'" :aria-label="w.fullPreview?'退出大画布':'放大画布'" @click="w.fullPreview=!w.fullPreview">{{w.fullPreview?'⊡':'⛶'}}</button></view></view><view class="canvas-area" ref="canvas" title="Ctrl + 鼠标滚轮缩放画布"><view class="canvas-holder" :class="w.device" :style="holderStyle"><view class="canvas-screen" :class="w.device" :style="canvasStyle"><AppExperience :key="w.currentId+':'+w.device" :theme="w.theme" :items="w.items" :categories="w.categories" :section-items="w.sectionItems" :demo="false" :editing="!w.interactive" :selected="w.selected" :page="w.page" :platform="w.device" :error="w.contentError" :startup-preview="w.startupPreview" :announcement-preview="w.announcementPreview" :update-preview="w.updatePreview" :studio="true" :template-key="w.currentId" @select="w.selectElement" @page="w.page=$event" @retry="w.refreshContent()"/></view></view></view><view class="canvas-status"><text>{{w.interactive?'可直接点击页面、搜索、分类和影片':'点击画布模块，选择要编辑的设计属性'}}</text><text>{{Math.round(scale*100)}}% · {{w.activeDevice.name}}</text></view></view>
<view class="inspector-panel" :class="{disabled:w.locked||w.busy}"><Inspector :key="w.tool+':'+w.selected" :theme="w.theme" :tool="w.tool" :section="w.selectedSection" :busy="w.busy" @upload="w.upload" @add-slide="w.addSlide()" @remove-module="w.removeModule()" @startup="w.startupPreview++"/></view>
</view>
</template>
<view v-if="w.error||w.message" class="feedback" :class="{error:!!w.error}" role="status"><text>{{w.error||w.message}}</text><button aria-label="关闭提示" @click="w.error='';w.message=''">×</button></view>
<view v-if="w.busy" class="busy-line"/>
</view>
<ClientIntegration v-if="w.dialog==='integration'" :integration="w.theme.integration" :platform="w.device" :busy="w.busy" :error="w.error" @change="w.theme.integration=$event" @close="w.dialog=''" @save="w.save()" @export="w.exportPackage()"/>
<view v-if="w.dialog&&w.dialog!=='integration'" class="modal-backdrop"><view class="workbench-modal" role="dialog" aria-modal="true" :aria-label="dialogTitles[w.dialog]"><view class="modal-heading"><view><text class="eyebrow">HETUN THEME STUDIO</text><text>{{dialogTitles[w.dialog]}}</text></view><button aria-label="关闭窗口" :disabled="w.busy" @click="w.dialog=''">×</button></view><template v-if="w.dialog==='guide'"><view class="guide-step"><text>01</text><view><text>选择或安装骨架</text><text>手机、平板、电视、网页分别安装和管理。未安装的端显示空状态。</text></view></view><view class="guide-step"><text>02</text><view><text>设计与离线预览</text><text>编辑品牌、轮播、模块外观、导航样式与装饰。使用本机素材预览布局，联网影片与播放由成品 App 对接。</text></view></view><view class="guide-step"><text>03</text><view><text>保存和导出</text><text>保存草稿保留修改，导出 ZIP 带上本机素材。本机发布只更新本机预览。</text></view></view><view class="guide-step"><text>04</text><view><text>运营中心安装</text><text>在独立运营中心上传主题包，再发布到对应端。导航与分类绑定、广告、会员与业务运营在运营中心管理。</text></view></view><button class="primary wide" @click="w.dialog=''">开始制作</button></template><template v-else-if="w.dialog==='remove'"><text class="modal-description">删除「{{w.dialogTarget?.name}}」及其本机草稿。已导出的主题包不会受影响。</text><view v-if="w.dialogTarget?.published" class="check-row"><checkbox :checked="w.allowUnpublish" @click="w.allowUnpublish=!w.allowUnpublish"/><text>同时解除这套主题的本机发布占用</text></view><view class="modal-actions"><button :disabled="w.busy" @click="w.dialog=''">取消</button><button class="danger filled" :disabled="w.busy||!w.serviceReady" @click="w.commitDialog()">确认删除</button></view></template><template v-else><text class="modal-description">{{w.dialog==='import'?'填写名称，再选择 ZIP 或 JSON 骨架包。安装时读取包内平台信息。':w.dialog==='duplicate'?'复制为独立主题，原主题与它的草稿继续保留。':'为主题设置一个容易辨认的名称。'}}</text><view class="field"><text>主题名称</text><input v-model="w.dialogName" maxlength="60" placeholder="例如：河豚酷影主题" @confirm="w.commitDialog()"/></view><text v-if="w.dialog==='import'" class="modal-hint">支持 hetun-skeleton v2。包内平台决定它所属的端。</text><view class="modal-actions"><button :disabled="w.busy" @click="w.dialog=''">取消</button><button class="primary" :disabled="w.busy||!w.serviceReady" @click="w.commitDialog()">{{w.dialog==='import'?'选择文件并安装':'确认'}}</button></view></template><text v-if="w.error" class="modal-error">{{w.error}}</text></view></view>
</view>
</template>
